#!/usr/bin/env python3
# ═══════════════════════════════════════════════════════════════════════════
# api.py — Merged Shopify Checker
# • Flask-style /shopify endpoint (bot.py compatible)
# • FastAPI /api/stream-checkout endpoint (streaming)
# • curl_cffi impersonation + aiohttp fallback
# ═══════════════════════════════════════════════════════════════════════════
import os
import re
import sys
import json
import time
import random
import uuid
import asyncio
import logging
import traceback
from logging.handlers import RotatingFileHandler
from urllib.parse import urlparse

import aiohttp
from fastapi import FastAPI, Request, Query
from fastapi.responses import JSONResponse, StreamingResponse
from fastapi.middleware.cors import CORSMiddleware
import uvicorn

# ═══ CONFIG ═══
PORT = int(os.environ.get("PORT", os.environ.get("API_PORT", "8000")))
HOST = os.environ.get("API_HOST", "0.0.0.0")
MIN_PRODUCT_PRICE = 5.0

# ═══ LOGGING ═══
_LOG_FMT = logging.Formatter(
    "%(asctime)s │ %(levelname)-7s │ %(name)s │ %(message)s",
    datefmt="%Y-%m-%d %H:%M:%S",
)
_root = logging.getLogger()
_root.setLevel(logging.INFO)

_console = logging.StreamHandler(sys.stdout)
_console.setFormatter(_LOG_FMT)
_root.addHandler(_console)

try:
    _file_all = RotatingFileHandler(
        "api.log", maxBytes=10 * 1024 * 1024, backupCount=3, encoding="utf-8"
    )
    _file_all.setFormatter(_LOG_FMT)
    _root.addHandler(_file_all)
except Exception:
    pass

log = logging.getLogger("api")


# ═══ TRY curl_cffi, FALLBACK to aiohttp ═══
try:
    from curl_cffi.requests import AsyncSession
    HAS_CURL_CFFI = True
    log.info("curl_cffi loaded successfully")
except ImportError:
    HAS_CURL_CFFI = False
    AsyncSession = None
    log.warning("curl_cffi not installed — falling back to aiohttp")


